# backend/app/zones/router.py
import uuid

from fastapi import APIRouter, Depends, HTTPException, status
from sqlalchemy.ext.asyncio import AsyncSession

from app.auth.deps import require_manager
from app.auth.models import User
from app.db import get_db
from app.zones.schemas import (
    ZoneAssignmentCreate,
    ZoneAssignmentOut,
    ZoneCreate,
    ZoneOut,
)
from app.zones.service import (
    AssignmentExistsError,
    RepNotFoundError,
    ZoneNotFoundError,
    assign_rep_to_zone,
    create_zone,
    get_zone,
    list_zones,
)

router = APIRouter(prefix="/api/v1/zones", tags=["zones"])


@router.post("", response_model=ZoneOut, status_code=status.HTTP_201_CREATED)
async def create_zone_endpoint(
    body: ZoneCreate,
    current_user: User = Depends(require_manager),
    db: AsyncSession = Depends(get_db),
) -> ZoneOut:
    zone = await create_zone(
        db, tenant_id=current_user.tenant_id, name=body.name, boundary=body.boundary.model_dump()
    )
    return zone


@router.get("", response_model=list[ZoneOut])
async def list_zones_endpoint(
    current_user: User = Depends(require_manager),
    db: AsyncSession = Depends(get_db),
) -> list[ZoneOut]:
    return await list_zones(db)


@router.get("/{zone_id}", response_model=ZoneOut)
async def get_zone_endpoint(
    zone_id: uuid.UUID,
    current_user: User = Depends(require_manager),
    db: AsyncSession = Depends(get_db),
) -> ZoneOut:
    zone = await get_zone(db, zone_id)
    if zone is None:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="zone not found")
    return zone


@router.post("/{zone_id}/assignments", response_model=ZoneAssignmentOut, status_code=status.HTTP_201_CREATED)
async def assign_rep_to_zone_endpoint(
    zone_id: uuid.UUID,
    body: ZoneAssignmentCreate,
    current_user: User = Depends(require_manager),
    db: AsyncSession = Depends(get_db),
) -> ZoneAssignmentOut:
    try:
        return await assign_rep_to_zone(
            db, tenant_id=current_user.tenant_id, zone_id=zone_id, rep_id=body.rep_id
        )
    except ZoneNotFoundError as exc:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="zone not found") from exc
    except RepNotFoundError as exc:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="rep not found") from exc
    except AssignmentExistsError as exc:
        raise HTTPException(
            status_code=status.HTTP_409_CONFLICT, detail="rep already assigned to this zone"
        ) from exc

from functools import lru_cache

from pydantic import field_validator, model_validator
from pydantic_settings import BaseSettings, SettingsConfigDict

DEFAULT_JWT_SECRET = "dev-secret-change-me-please-this-needs-to-be-at-least-32-bytes-long"


class Settings(BaseSettings):
    model_config = SettingsConfigDict(env_file=".env", env_file_encoding="utf-8")

    database_url: str = "sqlite+aiosqlite:///./dev.db"
    jwt_secret: str = DEFAULT_JWT_SECRET
    jwt_access_ttl_minutes: int = 15
    jwt_refresh_ttl_days: int = 30
    environment: str = "development"
    vapid_public_key: str = ""
    vapid_private_key: str = ""
    vapid_claim_email: str = "mailto:admin@example.com"

    @field_validator("jwt_secret", mode="after")
    @classmethod
    def validate_jwt_secret_length(cls, value: str) -> str:
        if len(value.encode("utf-8")) < 32:
            raise ValueError("JWT secret must be at least 32 bytes long")
        return value

    @model_validator(mode="after")
    def validate_jwt_secret_not_default_outside_development(self) -> "Settings":
        # A field_validator on jwt_secret can't see environment (declared after
        # it, and field validators only see earlier fields) - this needs the
        # fully-built model, hence a model_validator instead.
        if self.environment != "development" and self.jwt_secret == DEFAULT_JWT_SECRET:
            raise ValueError(
                "JWT_SECRET must be set to a non-default value when environment != 'development' "
                "- the default is public in source and would let anyone forge tokens"
            )
        return self


@lru_cache
def get_settings() -> Settings:
    return Settings()

